import * as React from "react";
import { cx } from "./cx";

export interface CarouselProps extends React.HTMLAttributes<HTMLDivElement> {
  "aria-label"?: string;
}

/** Native scroll snap; the buttons nudge. */
export function Carousel({ className, children, "aria-label": ariaLabel = "Carousel", ...props }: CarouselProps) {
  const trackRef = React.useRef<HTMLDivElement>(null);
  const nudge = (dir: 1 | -1) => {
    const track = trackRef.current;
    if (track) track.scrollBy({ left: dir * track.clientWidth * 0.8 });
  };
  return (
    <div className={cx("rs-carousel", className)} role="group" aria-label={ariaLabel} {...props}>
      <div ref={trackRef} className="rs-carousel-track" tabIndex={0}>
        {children}
      </div>
      <div className="rs-carousel-nav">
        <button type="button" className="rs-page" aria-label="Previous" onClick={() => nudge(-1)}>
          ‹
        </button>
        <button type="button" className="rs-page" aria-label="Next" onClick={() => nudge(1)}>
          ›
        </button>
      </div>
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Carousel: native scroll snap; the platform owns the physics ── */
.rs-carousel{position:relative}
.rs-carousel-track{display:flex;gap:var(--gutter);overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;scrollbar-width:none;-webkit-mask-image:linear-gradient(to right,transparent 0,#000 12px,#000 calc(100% - 12px),transparent 100%);mask-image:linear-gradient(to right,transparent 0,#000 12px,#000 calc(100% - 12px),transparent 100%);padding:2px 12px}
.rs-carousel-track::-webkit-scrollbar{display:none}
.rs-carousel-track>*{scroll-snap-align:start;flex-shrink:0}
.rs-carousel-nav{display:flex;gap:5px;margin-top:10px}
@media(prefers-reduced-motion:reduce){.rs-carousel-track{scroll-behavior:auto}}
